339	#[cfg(test)]
340	mod tests {
341	    use super::*;
342	    use serde_json::json;
343	
344	    fn spec_of(yaml: &str) -> ParamsSpec {
345	        serde_yaml::from_str(yaml).unwrap()
346	    }
347	
348	    fn supplied(pairs: &[(&str, Value)]) -> SuppliedParams {
349	        pairs
350	            .iter()
351	            .map(|(k, v)| (k.to_string(), v.clone()))
352	            .collect()
353	    }
