645	        let mut doc = json!(["${param.a}"]);
646	        let err = bind_document(&mut doc, &SuppliedParams::new(), BindMode::Strict).unwrap_err();
647	        assert!(matches!(err, CliError::UnknownParamRef { .. }));
648	        let mut doc = json!(7);
