459	/// Fetch a template (the launched version when `version` is `None`), binding the
460	/// Fetch a template (latest version when `version` is `None`), binding the
461	/// supplied params and env overrides into a runnable config document.
462	///
463	/// Ordering matters and mirrors the file-load path exactly: `${env:}` /
464	/// `${file:}` / `${secret:}` resolve **first** (with `env_overrides` taking
465	/// precedence over the process environment), then `${param.*}` binds. A supplied
466	/// param value is therefore never itself scanned for directives, so a caller
467	/// cannot use a param to read the server's environment or secret store.
468	pub async fn materialize(
469	    store: &TemplateStore,
470	    id: &str,
471	    version: u32,
472	    supplied: &SuppliedParams,
473	    env_overrides: &BTreeMap<String, String>,
474	) -> CliResult<MaterializedConfig> {
475	    // Takes a concrete version, never an `Option`: "no version given" is resolved
476	    // by `resolve_version` against the registry, so there is no code path where a
477	    // `None` here could quietly mean "the newest build".
478	    let record = store
479	        .template_get(id, Some(version))
480	        .await
481	        .map_err(|e| CliError::Internal(format!("template registry read: {e}")))?
482	        .ok_or_else(|| CliError::UnknownPipelineTemplate {
483	            id: id.to_string(),
484	            version: Some(version),
485	        })?;
486	
487	    let mut doc = parse_body(&record.body, record.format)?;
488	    let overlay: crate::interpolate::EnvOverlay = env_overrides
489	        .iter()
490	        .map(|(k, v)| (k.clone(), v.clone()))
491	        .collect();
492	    crate::interpolate::interpolate_value_with_env(&mut doc, &overlay)?;
493	    let bound = params::bind_document(&mut doc, supplied, BindMode::Strict)?;
494	    // Drop the declaration block: materialization is the moment params cease to
495	    // exist. Leaving it would make any later load re-run the bind pass with no
496	    // supplied values and reject the config for a "missing" required param —
497	    // and the param surface is already recorded on the template and echoed to
498	    // the caller, so nothing is lost.
499	    if let Some(map) = doc.as_object_mut() {
500	        map.remove(params::PARAMS_KEY);
501	    }
502	
503	    let body = serde_json::to_string(&doc)
504	        .map_err(|e| CliError::Internal(format!("re-serializing template body: {e}")))?;
505	    Ok(MaterializedConfig {
506	        template_id: record.id.clone(),
507	        version: record.version,
508	        name: record.name.clone(),
509	        body,
510	        params_redacted: bound.redacted(),
