1	//! The SQS `Source` implementation: long-poll `ReceiveMessage`, buffer to
2	//! `batch_size`, delete each page's receipt handles right before yielding it,
3	//! and terminate on `idle_timeout_secs` / `max_messages`.
4	
5	use crate::config::{MAX_RECEIVE_BATCH, SqsSourceConfig};
6	use aws_sdk_sqs::Client;
7	use aws_sdk_sqs::types::DeleteMessageBatchRequestEntry;
8	use faucet_core::{FaucetError, Stream, StreamPage};
9	use serde_json::Value;
10	use std::pin::Pin;
11	use std::time::{Duration, Instant};
12	
13	/// AWS SQS source. See the crate README for semantics.
14	pub struct SqsSource {
15	    config: SqsSourceConfig,
16	    client: Client,
17	}
18	
19	/// Decode one SQS message body: the parsed JSON value if the body is valid
20	/// JSON, otherwise the raw body wrapped as a JSON string. Pure.
21	pub(crate) fn decode_body(body: &str) -> Value {
22	    serde_json::from_str::<Value>(body).unwrap_or_else(|_| Value::String(body.to_string()))
23	}
24	
25	impl SqsSource {
26	    /// Create a new SQS source. Validates the config and builds the AWS client;
27	    /// no queue I/O happens until the first `ReceiveMessage` at stream time
28	    /// (construction is offline).
29	    pub async fn new(config: SqsSourceConfig) -> Result<Self, FaucetError> {
30	        config.validate()?;
31	        let client = faucet_common_sqs::build_client(
32	            config.region.as_deref(),
33	            config.endpoint_url.as_deref(),
34	            &config.credentials,
35	        )
36	        .await?;
37	        Ok(Self { config, client })
38	    }
39	
40	    /// Delete a page's receipt handles, chunked to the 10-entry API cap. A
41	    /// whole-request failure propagates as a typed error; per-entry failures
42	    /// are logged and left for SQS to redeliver (at-least-once).
43	    async fn delete_handles(&self, handles: &[String]) -> Result<(), FaucetError> {
44	        for chunk in handles.chunks(MAX_RECEIVE_BATCH as usize) {
45	            let entries: Vec<DeleteMessageBatchRequestEntry> = chunk
46	                .iter()
47	                .enumerate()
48	                .map(|(i, rh)| {
49	                    DeleteMessageBatchRequestEntry::builder()
50	                        .id(i.to_string())
51	                        .receipt_handle(rh)
52	                        .build()
53	                        .map_err(|e| {
54	                            FaucetError::Source(format!("sqs: delete entry build failed: {e}"))
55	                        })
56	                })
57	                .collect::<Result<_, _>>()?;
58	            let out = self
59	                .client
60	                .delete_message_batch()
61	                .queue_url(&self.config.queue_url)
62	                .set_entries(Some(entries))
63	                .send()
64	                .await
65	                .map_err(|e| {
66	                    FaucetError::Source(format!(
67	                        "sqs: DeleteMessageBatch on '{}' failed: {}",
68	                        self.config.queue_url,
69	                        e.into_service_error()
70	                    ))
71	                })?;
72	            for f in out.failed() {
73	                tracing::warn!(
74	                    queue = %self.config.queue_url,
75	                    id = f.id(),
76	                    code = f.code(),
77	                    "sqs: message delete failed; message will be redelivered"
78	                );
79	            }
80	        }
81	        Ok(())
82	    }
83	}
