85	#[faucet_core::async_trait]
86	impl faucet_core::Source for SqsSource {
87	    /// Drain the queue to termination (`idle_timeout_secs` / `max_messages` —
88	    /// at least one is enforced at construction) and return every message.
89	    async fn fetch_with_context(
90	        &self,
91	        context: &std::collections::HashMap<String, Value>,
92	    ) -> Result<Vec<Value>, FaucetError> {
93	        use futures::StreamExt;
94	        let mut pages = self.stream_pages(context, self.config.batch_size);
95	        let mut all = Vec::new();
96	        while let Some(page) = pages.next().await {
97	            all.extend(page?.records);
98	        }
99	        Ok(all)
100	    }
101	
102	    fn stream_pages<'a>(
103	        &'a self,
104	        _context: &'a std::collections::HashMap<String, Value>,
105	        _batch_size: usize,
106	    ) -> Pin<Box<dyn Stream<Item = Result<StreamPage, FaucetError>> + Send + 'a>> {
107	        let batch_size = self.config.batch_size;
108	        let chunk = if batch_size == 0 {
109	            usize::MAX
110	        } else {
111	            batch_size
112	        };
113	
114	        Box::pin(async_stream::try_stream! {
115	            let idle = self.config.idle_timeout_secs.map(Duration::from_secs);
116	            let max = self.config.max_messages;
117	            // `buffer` and `handles` stay index-aligned: one handle slot per
118	            // buffered record (None if a message somehow lacked a receipt
119	            // handle — such a record is emitted but not deleted, so SQS
