705	/// The minimum of a set of bookmarks under the replication ordering.
706	fn min_bookmark(vals: &[Value]) -> Option<Value> {
707	    let mut min: Option<&Value> = None;
708	    for v in vals {
709	        match min {
710	            None => min = Some(v),
711	            Some(m) if json_gt(m, v) => min = Some(v),
712	            _ => {}
713	        }
714	    }
715	    min.cloned()
716	}
