31	/// Config-level graph validation: the checks that need only the `nodes:` /
32	/// `edges:` spec, no connectors. Run as a fail-fast prelude to
33	/// [`build_topology`] (so a wiring typo is reported before any client is
34	/// constructed) and standalone by the template registry, which validates a
35	/// config it must not build connectors for (#444).
36	///
37	/// Node **arity** (a tee's fan-out, a join's labelled inputs, …) is validated by
38	/// [`faucet_core::topology::Topology::validate`] once the graph is built —
39	/// deliberately not re-implemented here, so the two can never disagree.
40	pub fn validate_topology_spec(cfg: &PipelineConfig) -> CliResult<()> {
41	    if !cfg.matrix.is_empty() {
42	        return Err(CliError::MatrixAndNodesBothPresent);
43	    }
44	    let spec = &cfg.pipeline;
45	    let mut known: Vec<String> = spec.nodes.keys().cloned().collect();
46	    known.sort_unstable();
47	    for edge in &spec.edges {
48	        for endpoint in [&edge.from, &edge.to] {
49	            if !spec.nodes.contains_key(endpoint) {
50	                return Err(CliError::EdgeEndpointMissing {
51	                    name: endpoint.clone(),
52	                    known: known.clone(),
53	                });
54	            }
55	        }
56	    }
57	    Ok(())
58	}
