60	/// Resolve one source/sink node's template `ref` + inline overrides into a
61	/// concrete `(kind, config)` pair.
62	fn resolve_connector(
63	    templates: &HashMap<String, ConnectorSpec>,
64	    legacy: &Option<ConnectorSpec>,
65	    template_ref: Option<&str>,
66	    kind_override: Option<&str>,
67	    config_override: Option<&Value>,
68	    node_id: &str,
69	    kind_label: &'static str,
70	) -> CliResult<(String, Value)> {
71	    let name = template_ref.unwrap_or("default");
72	    let base: ConnectorSpec = if name == "default" {
73	        templates
74	            .get("default")
75	            .cloned()
76	            .or_else(|| legacy.clone())
77	            .ok_or(CliError::MissingTemplate {
78	                kind: kind_label,
79	                row_id: node_id.to_string(),
80	            })?
81	    } else {
82	        templates
83	            .get(name)
84	            .cloned()
85	            .ok_or_else(|| CliError::UnknownTemplate {
86	                kind: kind_label,
87	                name: name.to_string(),
88	                row_id: node_id.to_string(),
89	                known: {
90	                    let mut k: Vec<String> = templates.keys().cloned().collect();
91	                    if legacy.is_some() {
92	                        k.push("default".to_string());
93	                    }
94	                    k.sort();
95	                    k
96	                },
97	            })?
98	    };
99	    let mut kind = base.kind;
100	    let mut config = base.config;
101	    if let Some(k) = kind_override {
102	        kind = k.to_string();
103	    }
104	    if let Some(c) = config_override {
105	        merge_value(&mut config, c.clone());
106	    }
107	    Ok((kind, config))
108	}
