110	/// Build a [`faucet_core::Topology`] from the config's `pipeline.nodes` /
111	/// `edges` block.
112	pub async fn build_topology(cfg: &PipelineConfig, auth: &AuthCatalog) -> CliResult<Topology> {
113	    // Cheap graph checks first, so a wiring typo never costs a connector build.
114	    validate_topology_spec(cfg)?;
115	
116	    let spec = &cfg.pipeline;
117	    let mut builder = Topology::builder();
118	
119	    // Deterministic node order (sorted by id) so errors/logs are stable.
120	    let mut node_ids: Vec<&String> = spec.nodes.keys().collect();
121	    node_ids.sort();
122	
123	    for id in &node_ids {
124	        let node = &spec.nodes[*id];
125	        let kind: NodeKind = match node {
126	            NodeSpec::Source {
127	                template,
128	                kind,
129	                config,
130	            } => {
131	                let (k, c) = resolve_connector(
132	                    &spec.sources,
133	                    &spec.source,
134	                    template.as_deref(),
135	                    kind.as_deref(),
136	                    config.as_ref(),
137	                    id,
138	                    "source",
139	                )?;
140	                NodeKind::Source(build_source(&k, c, auth, None).await?)
141	            }
142	            NodeSpec::Sink {
143	                template,
144	                kind,
145	                config,
146	            } => {
147	                let (k, c) = resolve_connector(
148	                    &spec.sinks,
149	                    &spec.sink,
150	                    template.as_deref(),
151	                    kind.as_deref(),
152	                    config.as_ref(),
153	                    id,
154	                    "sink",
155	                )?;
156	                NodeKind::Sink(build_sink(&k, c, auth).await?)
157	            }
158	            NodeSpec::Transform { transforms } => {
159	                let stages = compile_transforms(transforms)?;
160	                let compiled = stages
161	                    .iter()
162	                    .map(compile_stage)
163	                    .collect::<Result<Vec<_>, _>>()?;
164	                NodeKind::Transform(compiled)
165	            }
166	            NodeSpec::Tee {
167	                channel_capacity,
168	                fanout,
169	            } => NodeKind::Tee {
170	                capacity: *channel_capacity,
171	                fanout: *fanout,
172	            },
173	            NodeSpec::Merge => NodeKind::Merge,
174	            NodeSpec::Join(js) => NodeKind::Join(JoinNode {
175	                config: JoinConfig {
176	                    mode: js.mode,
177	                    build_key: js.build.key.clone(),
178	                    probe_key: js.probe.key.clone(),
179	                    projections: js.project.clone(),
180	                    on_missing: js.on_missing.clone(),
181	                    on_duplicate: js.on_duplicate,
182	                    on_collision: js.on_collision,
183	                    key_normalize: js.key_normalize,
184	                    max_build_records: js.max_build_records,
185	                },
186	                build_edge: js.build.edge.clone(),
187	                probe_edge: js.probe.edge.clone(),
188	            }),
189	        };
190	        builder = builder.node((*id).clone(), kind);
191	    }
192	
193	    // Edge endpoints were already validated by `validate_topology_spec` above —
194	    // before any connector was constructed — so just wire them.
195	    for e in &spec.edges {
196	        builder = match &e.label {
197	            Some(label) => builder.labelled_edge(e.from.clone(), e.to.clone(), label.clone()),
198	            None => builder.edge(e.from.clone(), e.to.clone()),
199	        };
200	    }
201	
202	    builder.build().map_err(|e| CliError::InvalidTopology {
203	        message: e.to_string(),
204	    })
205	}
