286	/// Build and run the topology, returning a [`RunSummary`] shaped like a matrix
287	/// run (one invocation per sink node, plus one per node failure under
288	/// `on_error: continue`).
289	pub async fn run_topology(
290	    cfg: &PipelineConfig,
291	    auth: &AuthCatalog,
292	    cancel: Option<CancellationToken>,
293	) -> CliResult<RunSummary> {
294	    let topo = build_topology(cfg, auth).await?;
295	
296	    let pipeline_name = cfg.name.clone().unwrap_or_else(|| "unnamed".to_string());
297	    let run_id = uuid::Uuid::now_v7().to_string();
298	
299	    let on_error = match cfg.execution.as_ref().map(|e| e.on_error) {
300	        Some(crate::config::OnError::Stop) => TopologyOnError::Propagate,
301	        _ => TopologyOnError::Continue,
302	    };
303	
304	    let mut opts = TopologyOptions::new(pipeline_name).with_on_error(on_error);
305	    opts.run_id = run_id;
306	
307	    if let Some(state) = &cfg.pipeline.state {
308	        opts = opts.with_state_store(crate::state::build_state_store(state).await?);
309	    }
310	    if let Some(dlq) = &cfg.pipeline.dlq {
311	        opts = opts.with_dlq(crate::executor::build_dlq_config(dlq).await?);
312	    }
313	    if let Some(c) = cancel {
314	        opts = opts.with_cancel(c);
315	    }
316	
317	    let result = topo.run(opts).await?;
318	
319	    let mut invocations: Vec<InvocationOutcome> = result
320	        .per_sink
321	        .into_iter()
322	        .map(|(node_id, records)| InvocationOutcome {
323	            row_id: node_id,
324	            parent_record_key: None,
325	            records_written: records,
326	            error: None,
327	            metrics: None,
328	        })
329	        .collect();
330	    invocations.sort_by(|a, b| a.row_id.cmp(&b.row_id));
331	
332	    for msg in result.errors {
333	        invocations.push(InvocationOutcome {
334	            row_id: "topology".to_string(),
335	            parent_record_key: None,
336	            records_written: 0,
337	            error: Some(msg),
338	            metrics: None,
339	        });
340	    }
341	
342	    Ok(RunSummary { invocations })
343	}
