1	//! MCP (Model Context Protocol) server surface for faucet (issue #420).
2	//!
3	//! A transport-agnostic JSON-RPC 2.0 dispatcher ([`handle_message`]) plus the
4	//! tool implementations ([`tools`]). Two front-ends drive it:
5	//!
6	//! - **stdio** — the `faucet mcp` subcommand ([`crate::commands::mcp`]), for
7	//!   local agents (Claude Desktop / Code).
8	//! - **Streamable HTTP** — the `/mcp` route mounted by `faucet serve --mcp`,
9	//!   which inherits serve's bearer-auth + RBAC + audit.
10	//!
11	//! The dispatcher re-exposes existing faucet capabilities (list / schema /
12	//! scaffold / validate / preview, and a gated `run_pipeline`) in the shape an
13	//! LLM agent speaks; it re-implements no pipeline logic. Read-only tools are
14	//! always available; the mutating `run_pipeline` tool appears only when the
15	//! context is constructed with `allow_mutations = true` (the `--allow-mutations`
16	//! flag, ANDed with the caller's RBAC scope on the HTTP transport).
17	
18	pub mod protocol;
19	pub mod tools;
20	
21	use crate::auth_catalog::AuthCatalog;
22	use protocol::*;
23	use serde_json::{Value, json};
24	
25	/// Everything a tool handler needs, independent of transport.
26	pub struct McpContext {
27	    /// Shared auth providers (for `preview`/`run_pipeline` connector builds).
28	    pub auth: AuthCatalog,
29	    /// Whether mutating tools (`run_pipeline`, `register_template`,
30	    /// `run_template`) are exposed and callable.
31	    pub allow_mutations: bool,
32	    /// The pipeline template registry (#444), when one is wired: `faucet serve
33	    /// --mcp` passes its own `--history` backend; `faucet mcp` needs
34	    /// `--template-store`. Absent = the template tools are not advertised at all,
35	    /// so an agent never sees a tool it cannot use.
36	    #[cfg(feature = "templates")]
37	    pub templates: Option<crate::templates::TemplateStore>,
38	}
39	
40	impl McpContext {
41	    pub fn new(auth: AuthCatalog, allow_mutations: bool) -> Self {
42	        Self {
43	            auth,
44	            allow_mutations,
45	            #[cfg(feature = "templates")]
46	            templates: None,
47	        }
48	    }
49	
50	    /// Attach a template registry, enabling the template tools.
51	    #[cfg(feature = "templates")]
52	    pub fn with_templates(mut self, store: crate::templates::TemplateStore) -> Self {
53	        self.templates = Some(store);
54	        self
55	    }
56	}
57	
58	/// Install a tracing subscriber that writes to **stderr** — stdout is reserved
59	/// for the JSON-RPC message stream in `faucet mcp` (stdio) mode.
60	pub fn install_stderr_tracing(level: &str) {
61	    use tracing_subscriber::EnvFilter;
62	    let filter = EnvFilter::try_new(level).unwrap_or_else(|_| EnvFilter::new("info"));
63	    let _ = tracing_subscriber::fmt()
64	        .with_env_filter(filter)
65	        .with_writer(std::io::stderr)
66	        .try_init();
67	}
68	
69	/// Server identity reported in `initialize`.
70	fn server_info() -> Value {
71	    json!({ "name": "faucet", "version": env!("CARGO_PKG_VERSION") })
72	}
73	
74	/// Handle one JSON-RPC message. Returns `Some(response_json)` for a request,
75	/// or `None` for a notification (which gets no response). A malformed message
76	/// yields a JSON-RPC parse/invalid-request error envelope.
77	pub async fn handle_message(ctx: &McpContext, raw: &str) -> Option<String> {
78	    let req: JsonRpcRequest = match serde_json::from_str(raw) {
79	        Ok(r) => r,
80	        Err(e) => {
81	            return Some(render(error_no_id(
82	                PARSE_ERROR,
83	                format!("parse error: {e}"),
84	            )));
85	        }
86	    };
87	
88	    // Notifications (no id) get no response, whatever the method.
89	    if req.is_notification() {
90	        return None;
91	    }
92	    let id = req.id.clone().unwrap_or(Value::Null);
93	
94	    let resp = match req.method.as_str() {
95	        "initialize" => success(
96	            id,
97	            json!({
98	                "protocolVersion": PROTOCOL_VERSION,
99	                "capabilities": { "tools": {}, "resources": {} },
100	                "serverInfo": server_info(),
101	            }),
102	        ),
103	        "ping" => success(id, json!({})),
104	        "tools/list" => {
105	            let defs = tools::tool_defs(ctx);
106	            success(id, json!({ "tools": defs }))
107	        }
108	        "tools/call" => match req.params.get("name").and_then(Value::as_str) {
109	            Some(name) => {
110	                let empty = json!({});
111	                let args = req.params.get("arguments").unwrap_or(&empty);
112	                let result = tools::call_tool(ctx, name, args).await;
113	                success(id, result)
114	            }
115	            None => error(id, INVALID_PARAMS, "tools/call requires a 'name' parameter"),
116	        },
117	        "resources/list" => success(id, json!({ "resources": [] })),
118	        "resources/read" => error(
119	            id,
120	            INVALID_PARAMS,
121	            "no readable resources are exposed in this version",
122	        ),
123	        other => error(id, METHOD_NOT_FOUND, format!("unknown method '{other}'")),
124	    };
125	    Some(render(resp))
126	}
127	
128	/// Drive an MCP session over any byte streams: read newline-delimited JSON-RPC
129	/// from `reader`, write each response (one JSON object per line) to `writer`.
130	/// Blank lines are skipped; notifications produce no output. Returns when the
131	/// reader hits EOF. The `faucet mcp` stdio command wraps stdin/stdout with
132	/// this; tests drive it with in-memory buffers.
133	pub async fn serve_stdio<R, W>(ctx: &McpContext, reader: R, writer: &mut W) -> std::io::Result<()>
134	where
135	    R: tokio::io::AsyncBufRead + Unpin,
136	    W: tokio::io::AsyncWrite + Unpin,
137	{
138	    use tokio::io::{AsyncBufReadExt, AsyncWriteExt};
