185	pub async fn call_tool(ctx: &McpContext, name: &str, args: &Value) -> Value {
186	    let result: Result<String, String> = match name {
187	        "list_connectors" => list_connectors(args),
188	        "get_connector_schema" => get_connector_schema(args),
189	        "scaffold_config" => scaffold_config(args),
190	        "validate_config" => validate_config(ctx, args).await,
191	        "preview" => preview(ctx, args).await,
192	        "run_pipeline" => {
193	            if !ctx.allow_mutations {
194	                Err("run_pipeline is disabled; start the MCP server with --allow-mutations to enable mutating tools".to_string())
195	            } else {
196	                run_pipeline(ctx, args).await
197	            }
198	        }
199	        #[cfg(feature = "templates")]
200	        "list_templates" => list_templates(ctx).await,
201	        #[cfg(feature = "templates")]
202	        "get_template" => get_template(ctx, args).await,
203	        #[cfg(feature = "templates")]
204	        "register_template" => {
205	            if !ctx.allow_mutations {
206	                Err(MUTATION_GATE.to_string())
207	            } else {
208	                register_template(ctx, args).await
209	            }
210	        }
211	        #[cfg(feature = "templates")]
212	        "launch_template" => {
213	            if !ctx.allow_mutations {
214	                Err(MUTATION_GATE.to_string())
215	            } else {
216	                launch_template(ctx, args).await
217	            }
218	        }
219	        #[cfg(feature = "templates")]
220	        "rollback_template" => {
221	            if !ctx.allow_mutations {
222	                Err(MUTATION_GATE.to_string())
223	            } else {
224	                rollback_template(ctx, args).await
225	            }
226	        }
227	        #[cfg(feature = "templates")]
228	        "deprecate_template" => {
229	            if !ctx.allow_mutations {
230	                Err(MUTATION_GATE.to_string())
231	            } else {
232	                deprecate_template(ctx, args).await
233	            }
234	        }
235	        #[cfg(feature = "templates")]
236	        "run_template" => {
237	            if !ctx.allow_mutations {
238	                Err(MUTATION_GATE.to_string())
239	            } else {
240	                run_template(ctx, args).await
241	            }
242	        }
243	        other => Err(format!("unknown tool '{other}'")),
244	    };
245	    match result {
246	        Ok(text) => tool_text(text),
247	        // Redact any resolved secret material that reached an error string.
248	        Err(msg) => tool_error(crate::secrets::registry::redact(&msg)),
249	    }
250	}
251	
252	fn str_arg<'a>(args: &'a Value, key: &str) -> Result<&'a str, String> {
253	    args.get(key)
254	        .and_then(Value::as_str)
255	        .ok_or_else(|| format!("missing required string argument '{key}'"))
256	}
257	
258	fn tier_of(kind: &str, is_source: bool) -> &'static str {
259	    crate::conformance::tier_for(kind, is_source).as_str()
260	}
261	
262	fn list_connectors(args: &Value) -> Result<String, String> {
263	    let filter = args.get("kind").and_then(Value::as_str).unwrap_or("all");
264	    let want = |c: &str| filter == "all" || filter == c;
265	
266	    let mut out = json!({});
267	    let obj = out.as_object_mut().unwrap();
268	    if want("source") {
269	        let sources: Vec<Value> = crate::registry::source_descriptions()
270	            .into_iter()
271	            .map(|(name, desc)| json!({ "name": name, "description": desc, "tier": tier_of(name, true) }))
272	            .collect();
273	        obj.insert("sources".into(), json!(sources));
274	    }
275	    if want("sink") {
276	        let sinks: Vec<Value> = crate::registry::sink_descriptions()
277	            .into_iter()
278	            .map(|(name, desc)| json!({ "name": name, "description": desc, "tier": tier_of(name, false) }))
279	            .collect();
280	        obj.insert("sinks".into(), json!(sinks));
281	    }
282	    if want("transform") {
283	        let transforms: Vec<Value> = crate::transforms::transform_descriptions()
284	            .into_iter()
285	            .map(|(name, desc)| json!({ "name": name, "description": desc }))
286	            .collect();
