name: dry
pipeline:
  sources:
    o: {{ type: csv, config: {{ path: {csv} }} }}
  sinks:
    out: {{ type: jsonl, config: {{ path: {out} }} }}
  nodes:
    s: {{ kind: source, ref: o }}
    w: {{ kind: sink, ref: out }}
  edges:
    - {{ from: s, to: w }}
"#,
