            &cfg,
            vec![PathBuf::from("./dlq.jsonl")],
            None,
            Path::new("./failed.jsonl"),
            None,
            DlqDecryptor::default(),
        )
        .expect("builds");
        assert!(node.quality.is_some(), "checks are idempotent; keep them");
    }
}
