14	/// Validate a user-supplied `--reason` filter against the closed set of DLQ
15	/// reason values (`partial` / `dlq_all` / `quality` / `schema_drift` /
16	/// `contract`). Returns the owned string on success.
17	pub fn validate_reason(reason: Option<&str>) -> CliResult<Option<String>> {
18	    match reason {
19	        None => Ok(None),
20	        Some(r) => {
21	            if DlqReason::from_serde_str(r).is_some() {
22	                Ok(Some(r.to_owned()))
23	            } else {
24	                let allowed = DlqReason::ALL
25	                    .iter()
26	                    .map(|r| r.as_str())
27	                    .collect::<Vec<_>>()
28	                    .join(", ");
29	                Err(CliError::Config(format!(
30	                    "unknown --reason '{r}'; expected one of: {allowed}"
31	                )))
32	            }
33	        }
34	    }
35	}
