59	/// Convert a JSON value into an owned DuckDB parameter value.
60	fn json_to_duck(v: &Value) -> DuckValue {
61	    match v {
62	        Value::Null => DuckValue::Null,
63	        Value::Bool(b) => DuckValue::Boolean(*b),
64	        Value::Number(n) => {
65	            if let Some(i) = n.as_i64() {
