37	/// Derive the default "replay-failed" DLQ path for a set of source files:
38	/// a `replay-failed.jsonl` sibling next to the first file (or, when the
39	/// source is a single file `x.jsonl`, `x.replay-failed.jsonl`). Guaranteed
40	/// distinct from any single-file source so replay can never re-feed itself.
41	pub fn default_failed_dlq_path(from_files: &[PathBuf]) -> PathBuf {
42	    match from_files {
43	        [only] => {
44	            let stem = only.file_stem().and_then(|s| s.to_str()).unwrap_or("dlq");
45	            let parent = only.parent().unwrap_or_else(|| Path::new("."));
46	            parent.join(format!("{stem}.replay-failed.jsonl"))
47	        }
48	        _ => {
49	            let parent = from_files
50	                .first()
51	                .and_then(|p| p.parent())
52	                .unwrap_or_else(|| Path::new("."));
53	            parent.join("replay-failed.jsonl")
54	        }
55	    }
56	}
