90	/// their own (they need parent records to resolve `${parent.path}`), so only
91	/// roots are eligible.
92	pub fn select_replay_node(nodes: Vec<ExpandedNode>, row: Option<&str>) -> CliResult<ExpandedNode> {
93	    let roots = || nodes.iter().filter(|n| matches!(n.role, NodeRole::Root));
94	    let chosen = match row {
95	        Some(id) => nodes.iter().position(|n| n.id == id).ok_or_else(|| {
96	            CliError::Config(format!(
97	                "row '{id}' not found in config (roots: {})",
98	                roots()
99	                    .map(|n| n.id.as_str())
100	                    .collect::<Vec<_>>()
101	                    .join(", ")
102	            ))
103	        })?,
104	        None => nodes
105	            .iter()
106	            .position(|n| matches!(n.role, NodeRole::Root))
107	            .ok_or_else(|| CliError::Config("config has no root pipeline to replay".into()))?,
108	    };
109	    let node = &nodes[chosen];
110	    if !matches!(node.role, NodeRole::Root) {
111	        return Err(CliError::Config(format!(
112	            "row '{}' is a child node; only root pipelines can be replayed directly",
113	            node.id
114	        )));
115	    }
116	    Ok(nodes.into_iter().nth(chosen).expect("index in range"))
