119	/// Build the replay node from the referenced config: expand it, pick the
120	/// target root, swap its source for a [`DlqReaderSource`] over `from_files`,
121	/// force at-least-once delivery, drop the state block (a replay is a fresh
122	/// whole-location read), and point failures at a *fresh* DLQ so a replayed
123	/// row that fails again can never re-feed the source location.
124	pub fn build_replay_node(
125	    cfg: &PipelineConfig,
126	    from_files: Vec<PathBuf>,
127	    reason: Option<String>,
128	    failed_dlq: &Path,
129	    row: Option<&str>,
130	    decryptor: DlqDecryptor,
131	) -> CliResult<ExpandedNode> {
132	    // Loop guard: the fresh DLQ must not be one of the source files.
133	    if from_files.iter().any(|f| same_file(f, failed_dlq)) {
134	        return Err(CliError::Config(format!(
135	            "replay-failed DLQ '{}' is one of the source files — replayed failures would re-feed \
136	             the source; pass a different --failed-dlq",
137	            failed_dlq.display()
138	        )));
139	    }
140	
141	    let nodes = expand(cfg)?;
142	    let original_dlq = nodes
143	        .iter()
144	        .find(|n| matches!(n.role, NodeRole::Root))
145	        .and_then(|n| n.dlq.clone());
146	    let mut node = select_replay_node(nodes, row)?;
147	
148	    let reader = DlqReaderSource::new(from_files, reason, decryptor);
149	    node.source_override = Some(SourceOverride::new(Box::new(reader)));
150	
151	    // A DLQ envelope's `payload` is the record as it entered the *write* path —
152	    // i.e. already transformed and already masked (the masking pass runs first per
153	    // page, so quarantine and write-failure envelopes both hold masked values).
154	    // Re-running those two passes on replay would apply them a second time, and
155	    // neither is idempotent: the `hash` transform and masking's `hash`/`tokenize`
156	    // actions would produce H(H(x)), breaking the joinability masking exists to
157	    // guarantee; `set` would re-stamp `${now.*}` with the replay time; `cast` /
158	    // `json_parse` / `split` would re-run against already-converted values. So a
159	    // replay skips both (#456 H3).
160	    //
161	    // The quality and contract passes are deliberately kept: they are pure
162	    // predicates over the record, so re-checking is idempotent — and a replay is
163	    // exactly when you want them re-enforced.
164	    node.transforms.clear();
165	    node.masking = None;
166	
167	    // A replay reads the whole DLQ location once — no bookmarking, and never
168	    // exactly-once (the reader is not a deterministic-replay source).
169	    node.state = None;
170	    node.delivery = DeliveryMode::AtLeastOnce;
171	    node.dlq = Some(failed_dlq_spec(failed_dlq, original_dlq.as_ref()));
172	    Ok(node)
173	}
