102	/// Config-level graph validation: the checks that need only the `nodes:` /
103	/// `edges:` spec, no connectors. Run as a fail-fast prelude to
104	/// [`build_topology`] (so a wiring typo is reported before any client is
105	/// constructed) and standalone by the template registry, which validates a
106	/// config it must not build connectors for (#444).
107	///
108	/// Node **arity** (a tee's fan-out, a join's labelled inputs, …) is validated by
109	/// [`faucet_core::topology::Topology::validate`] once the graph is built —
110	/// deliberately not re-implemented here, so the two can never disagree.
111	pub fn validate_topology_spec(cfg: &PipelineConfig) -> CliResult<()> {
112	    if !cfg.matrix.is_empty() {
113	        return Err(CliError::MatrixAndNodesBothPresent);
114	    }
115	    // Exactly-once is not implemented for node graphs: there is no per-sink
116	    // commit-token/watermark path here. The matrix path gates this combination in
117	    // `expand`, which topology mode never runs — so without this check the run
118	    // would silently execute at-least-once and duplicate on retry (#456 H2).
119	    if cfg.delivery == faucet_core::DeliveryMode::ExactlyOnce {
120	        return Err(CliError::Config(
121	            "`delivery: exactly_once` is not supported in topology mode (`pipeline.nodes`): a \
122	             node graph has no atomic commit-token path, so the run would silently be \
123	             at-least-once. Use the matrix form (`pipeline.source`/`sink` + `matrix:`) for \
124	             exactly-once, or make the sinks idempotent with `write_mode: upsert` and set \
125	             `delivery: at_least_once`"
126	                .into(),
127	        ));
128	    }
129	    let spec = &cfg.pipeline;
130	    let mut known: Vec<String> = spec.nodes.keys().cloned().collect();
131	    known.sort_unstable();
132	    for edge in &spec.edges {
133	        for endpoint in [&edge.from, &edge.to] {
134	            if !spec.nodes.contains_key(endpoint) {
135	                return Err(CliError::EdgeEndpointMissing {
136	                    name: endpoint.clone(),
137	                    known: known.clone(),
138	                });
139	            }
140	        }
141	    }
142	    Ok(())
143	}
