  sink: {{ type: jsonl, config: {{ path: ./out.jsonl }} }}
  dlq:
    sink: {{ type: jsonl, config: {{ path: ./dlq.jsonl }} }}
"#
        );
        PipelineConfig::from_text(&yaml, Path::new("test.yaml")).expect("parses")
    }

