#[test]
fn shares_a_column_detects_overlap_and_its_absence() {
    let cols = vec!["id".to_string(), "name".to_string()];
    let present: Vec<&String> = cols.iter().collect();
    assert!(shares_a_column(&json!({"id": 1}), &present));
    assert!(shares_a_column(&json!({"name": "x", "extra": 9}), &present));
    // No overlap → skipped (would otherwise be an all-NULL row, #466 L1).
    assert!(!shares_a_column(&json!({"unrelated": 1}), &present));
    assert!(!shares_a_column(&json!({}), &present));
    // A non-object never shares a column.
    assert!(!shares_a_column(&json!(42), &present));
    assert!(!shares_a_column(&json!(null), &present));
}

