1	//! Pure SQL / payload builders for the Redshift sink.
2	//!
3	//! Everything here is I/O-free and unit-tested: the `COPY` statement, the
4	//! multi-row `INSERT` statement, and the CSV / JSONL serializers. Keeping them
5	//! pure means the exact SQL a live cluster receives is asserted in tests without
6	//! a database.
7	
8	use crate::config::RedshiftCopyFormat;
9	use faucet_core::FaucetError;
10	use faucet_core::util::quote_ident;
11	use serde_json::Value;
12	
13	/// Build a schema-qualified, quoted table reference (`"schema"."table"` or
14	/// `"table"`).
15	pub(crate) fn qualified_table_ref(schema: Option<&str>, table: &str) -> String {
16	    match schema {
17	        Some(s) => format!("{}.{}", quote_ident(s), quote_ident(table)),
18	        None => quote_ident(table),
19	    }
20	}
21	
22	/// Render a value as a single-quoted SQL string literal, doubling interior
23	/// single quotes so it is injection-safe.
24	pub(crate) fn sql_string_literal(s: &str) -> String {
25	    format!("'{}'", s.replace('\'', "''"))
26	}
27	
28	/// The `s3://bucket/key` URI for a staged object.
29	pub(crate) fn s3_uri(bucket: &str, key: &str) -> String {
30	    format!("s3://{bucket}/{key}")
31	}
32	
33	/// Build the Redshift `COPY` statement.
34	///
35	/// For JSONL the column list is omitted (`FORMAT AS JSON 'auto'` maps by key
36	/// name); for CSV the destination column order is passed explicitly. `s3_path`,
37	/// `iam_role`, and `region` are emitted as escaped string literals.
38	pub(crate) fn copy_statement(
39	    table_ref: &str,
40	    columns: Option<&[String]>,
41	    s3_path: &str,
42	    iam_role: &str,
43	    region: Option<&str>,
44	    format: RedshiftCopyFormat,
45	) -> String {
46	    let col_clause = match (format, columns) {
47	        // CSV needs an explicit, ordered column list.
48	        (RedshiftCopyFormat::Csv, Some(cols)) if !cols.is_empty() => {
49	            let list = cols
50	                .iter()
51	                .map(|c| quote_ident(c))
52	                .collect::<Vec<_>>()
53	                .join(", ");
54	            format!(" ({list})")
55	        }
56	        _ => String::new(),
57	    };
58	
59	    let format_clause = match format {
60	        RedshiftCopyFormat::Jsonl => "FORMAT AS JSON 'auto'".to_string(),
61	        RedshiftCopyFormat::Csv => "FORMAT AS CSV".to_string(),
62	    };
63	
64	    let mut sql = format!(
65	        "COPY {table_ref}{col_clause} FROM {} IAM_ROLE {} {format_clause}",
66	        sql_string_literal(s3_path),
67	        sql_string_literal(iam_role),
68	    );
69	    if let Some(r) = region.filter(|r| !r.trim().is_empty()) {
70	        sql.push_str(&format!(" REGION {}", sql_string_literal(r)));
71	    }
72	    sql
73	}
74	
75	/// Build a multi-row `INSERT INTO table (cols) VALUES ($1,$2),($3,$4)…`.
76	/// Placeholders are numbered `$1..=$(num_rows*columns.len())`.
77	pub(crate) fn insert_statement(table_ref: &str, columns: &[String], num_rows: usize) -> String {
78	    let col_list = columns
79	        .iter()
80	        .map(|c| quote_ident(c))
81	        .collect::<Vec<_>>()
82	        .join(", ");
83	    let num_cols = columns.len();
84	    let mut tuples = Vec::with_capacity(num_rows);
85	    for row in 0..num_rows {
86	        let start = row * num_cols + 1;
87	        let placeholders = (0..num_cols)
88	            .map(|c| format!("${}", start + c))
89	            .collect::<Vec<_>>()
90	            .join(", ");
91	        tuples.push(format!("({placeholders})"));
92	    }
93	    format!(
94	        "INSERT INTO {table_ref} ({col_list}) VALUES {}",
95	        tuples.join(", ")
96	    )
97	}
98	
99	/// The set of destination columns present in at least one record, preserving
100	/// the destination's declared order.
101	pub(crate) fn columns_present<'a>(
102	    records: &[Value],
103	    table_columns: &'a [String],
104	) -> Vec<&'a String> {
105	    table_columns
106	        .iter()
107	        .filter(|col| {
108	            records
109	                .iter()
110	                .any(|r| r.as_object().is_some_and(|o| o.contains_key(col.as_str())))
111	        })
112	        .collect()
113	}
114	
115	/// Whether `record` (a JSON object) has at least one key matching a column in
116	/// `present`. A record that shares no column with the table carries nothing for
117	/// this destination; binding it would emit an all-NULL row, so the INSERT path
118	/// skips it (#466 L1). A non-object never shares a column.
119	pub(crate) fn shares_a_column(record: &Value, present: &[String]) -> bool {
120	    record
121	        .as_object()
122	        .is_some_and(|o| present.iter().any(|c| o.contains_key(c.as_str())))
123	}
124	
125	/// Serialize records as newline-delimited JSON (JSONL) bytes for `FORMAT AS
126	/// JSON 'auto'`.
127	pub(crate) fn serialize_jsonl(records: &[Value]) -> Result<Vec<u8>, FaucetError> {
128	    let mut buf = Vec::new();
129	    for record in records {
130	        let line = serde_json::to_vec(record)
131	            .map_err(|e| FaucetError::Sink(format!("redshift: JSON serialization failed: {e}")))?;
132	        buf.extend_from_slice(&line);
133	        buf.push(b'\n');
134	    }
135	    Ok(buf)
136	}
137	
138	/// Render one CSV cell from a JSON value (RFC-4180 quoting).
139	fn csv_cell(v: Option<&Value>) -> String {
140	    match v {
141	        None | Some(Value::Null) => String::new(),
142	        Some(Value::String(s)) => quote_csv(s),
143	        Some(Value::Bool(b)) => b.to_string(),
144	        Some(Value::Number(n)) => n.to_string(),
