//! #465 Part 1 — cross-check the registry capability *allowlists* against the
//! trait methods on a real, built connector, so the two can never silently
//! drift.
//!
//! The gates in `expand.rs` / `topology.rs` trust the hand-maintained allowlists
//! in `registry.rs` (`IDEMPOTENT_SINK_KINDS`, `UPSERT_SINK_KINDS`,
//! `SCHEMA_EVOLUTION_SINK_KINDS`, `EXACTLY_ONCE_SOURCE_KINDS`,
//! `DISCOVER_SOURCE_KINDS`). The pipeline / connectors trust the trait methods
//! (`Sink::supports_idempotent_writes`, `supported_write_modes`,
//! `supports_schema_evolution`; `Source::supports_exactly_once`,
//! `supports_discover`). If those two ever disagree, the worst case is a run that
//! passes the exactly-once gate but silently loses the guarantee. This test
//! builds each connector and asserts allowlist == trait for every dimension.
//!
//! **Coverage & the skip-list.** A connector whose `new()` opens a live
//! connection eagerly (the sqlx `.connect()` sinks, tiberius, Spanner, Iceberg
//! catalog) cannot be constructed in an offline unit test. Those are listed in
//! [`CONNECT_REQUIRED`] with a reason, and skipped. The list is **shrink-only**:
//! if a connector *not* on it fails to build, the test fails — a new build
//! failure must be a conscious decision, never a silent coverage loss. In CI the
//! test runs under `--all-features`, so every compiled connector is exercised.

use std::collections::HashMap;

use faucet_cli::auth_catalog::AuthCatalog;
use faucet_cli::registry;
use serde_json::{Map, Value, json};

/// Connectors that cannot be constructed without a live endpoint / credentials,
/// so this offline test cannot obtain an instance to probe. Each carries the
/// reason. Their capability methods are literal constants (verified by review
/// and by the crate's own testcontainers integration tests) — this list is the
/// documented, shrink-only boundary of what the offline check can reach.
const CONNECT_REQUIRED: &[(&str, &str)] = &[
    ("postgres", "sqlx PgPoolOptions::connect() opens a connection eagerly"),
    ("mysql", "sqlx MySqlPoolOptions::connect() opens a connection eagerly"),
    ("mssql", "tiberius+bb8 pool connects and creates the table in new()"),
    ("mssql-cdc", "tiberius connects in new()"),
    ("spanner", "SpannerConnection::connect() opens a gRPC session in new()"),
    ("iceberg", "the catalog client connects in new()"),
    ("postgres-cdc", "opens a replication connection / slot in new()"),
    ("mysql-cdc", "opens a binlog replication connection in new()"),
    ("mongodb-cdc", "opens a change stream in new()"),
];

/// Per-kind config overrides where the generic synthesizer produces a value the
/// connector's `new()` rejects (e.g. a SQLite URL is not an `http://` URL).
/// Keyed by `"source:<kind>"` / `"sink:<kind>"`.
fn config_override(key: &str) -> Option<Value> {
    let v = match key {
        "sink:sqlite" | "source:sqlite" => json!({
            "database_url": "sqlite::memory:",
            "connection_url": "sqlite::memory:",
            "table_name": "t",
            "query": "SELECT 1",
            "column_mapping": "json_column",
        }),
        _ => return None,
    };
    Some(v)
}

fn is_connect_required(kind: &str) -> bool {
    CONNECT_REQUIRED.iter().any(|(k, _)| *k == kind)
}

/// Synthesize a minimal, type-valid config instance from a connector's JSON
/// Schema: resolve `$ref`, take the first `enum`/`oneOf` variant, and fill every
/// `required` field with a field-name-aware placeholder. Enough to satisfy
/// `serde` + a lazily-constructing `new()`.
fn synthesize(schema: &Value, defs: &Map<String, Value>, field: &str, depth: u32) -> Value {
    if depth > 12 {
        return Value::Null;
    }
    // $ref → resolve against the root $defs.
    if let Some(r) = schema.get("$ref").and_then(Value::as_str) {
        let name = r.rsplit('/').next().unwrap_or(r);
        if let Some(target) = defs.get(name) {
            return synthesize(target, defs, field, depth + 1);
        }
        return Value::Null;
    }
    if let Some(c) = schema.get("const") {
        return c.clone();
    }
    if let Some(vals) = schema.get("enum").and_then(Value::as_array) {
        if let Some(first) = vals.first() {
            return first.clone();
        }
    }
    for combinator in ["oneOf", "anyOf", "allOf"] {
        if let Some(variants) = schema.get(combinator).and_then(Value::as_array) {
            if let Some(first) = variants.first() {
                return synthesize(first, defs, field, depth + 1);
            }
        }
    }

    let ty = schema
        .get("type")
        .and_then(|t| match t {
            Value::String(s) => Some(s.clone()),
            Value::Array(a) => a.iter().filter_map(Value::as_str).find(|s| *s != "null").map(String::from),
            _ => None,
        })
        .or_else(|| schema.get("properties").map(|_| "object".to_string()));

    match ty.as_deref() {
        Some("object") | None if schema.get("properties").is_some() => {
            let props = schema
                .get("properties")
                .and_then(Value::as_object)
                .cloned()
                .unwrap_or_default();
            let required: Vec<String> = schema
                .get("required")
                .and_then(Value::as_array)
                .map(|a| a.iter().filter_map(Value::as_str).map(String::from).collect())
                .unwrap_or_default();
            let mut obj = Map::new();
            for name in &required {
                if let Some(prop) = props.get(name) {
                    obj.insert(name.clone(), synthesize(prop, defs, name, depth + 1));
                }
            }
            Value::Object(obj)
        }
        Some("string") => Value::String(placeholder_string(field)),
        Some("integer") | Some("number") => json!(1),
        Some("boolean") => json!(false),
        Some("array") => json!([]),
        _ => Value::Null,
    }
}

/// A plausible placeholder for a required string field, keyed off its name so a
/// lazily-validating `new()` (URL/DSN parsing) still accepts it.
fn placeholder_string(field: &str) -> String {
    let f = field.to_ascii_lowercase();
    if f.contains("broker") || f.contains("bootstrap") {
        "localhost:9092".into()
    } else if f.contains("url") || f.contains("uri") || f.contains("endpoint") {
        "http://localhost:1/".into()
    } else if f.contains("host") {
        "localhost".into()
    } else if f.contains("path") || f.contains("file") {
        "/tmp/faucet_parity_probe".into()
    } else if f.contains("region") {
        "us-east-1".into()
    } else {
        "x".into()
    }
}

fn minimal_config(kind_key: &str, schema: &Value) -> Value {
    if let Some(o) = config_override(kind_key) {
        return o;
    }
    let empty = Map::new();
    let defs = schema
        .get("$defs")
        .or_else(|| schema.get("definitions"))
        .and_then(Value::as_object)
        .unwrap_or(&empty);
    synthesize(schema, defs, "", 0)
}

/// Outcome of trying to probe one connector.
enum Probe {
    Checked,
    Skipped(String),
}

async fn probe_sink(kind: &str) -> Probe {
    if is_connect_required(kind) {
        return Probe::Skipped("connect-required".into());
    }
    let schema = match registry::sink_schema(kind) {
        Ok(s) => s,
        Err(e) => return Probe::Skipped(format!("no schema: {e}")),
    };
    let cfg = minimal_config(&format!("sink:{kind}"), &schema);
    let auth: AuthCatalog = HashMap::new();
    let sink = match registry::build_sink(kind, cfg, &auth).await {
        Ok(s) => s,
        Err(e) => return Probe::Skipped(format!("build failed: {e}")),
    };

    assert_eq!(
        registry::sink_supports_idempotent_writes(kind),
        sink.supports_idempotent_writes(),
        "{kind}: IDEMPOTENT_SINK_KINDS ({}) disagrees with Sink::supports_idempotent_writes ({})",
        registry::sink_supports_idempotent_writes(kind),
        sink.supports_idempotent_writes(),
    );
    assert_eq!(
        registry::sink_supports_schema_evolution(kind),
        sink.supports_schema_evolution(),
        "{kind}: SCHEMA_EVOLUTION_SINK_KINDS disagrees with Sink::supports_schema_evolution",
    );
    assert_eq!(
        registry::sink_supported_write_modes(kind),
        sink.supported_write_modes(),
        "{kind}: sink_supported_write_modes() disagrees with Sink::supported_write_modes()",
    );
    Probe::Checked
}

async fn probe_source(kind: &str) -> Probe {
    if is_connect_required(kind) {
        return Probe::Skipped("connect-required".into());
    }
    let schema = match registry::source_schema(kind) {
        Ok(s) => s,
        Err(e) => return Probe::Skipped(format!("no schema: {e}")),
    };
    let cfg = minimal_config(&format!("source:{kind}"), &schema);
    let auth: AuthCatalog = HashMap::new();
    let source = match registry::build_source(kind, cfg, &auth, None).await {
        Ok(s) => s,
        Err(e) => return Probe::Skipped(format!("build failed: {e}")),
    };

    assert_eq!(
        registry::source_supports_exactly_once(kind),
        source.supports_exactly_once(),
        "{kind}: EXACTLY_ONCE_SOURCE_KINDS disagrees with Source::supports_exactly_once",
    );
    assert_eq!(
        registry::source_supports_discover(kind),
        source.supports_discover(),
        "{kind}: DISCOVER_SOURCE_KINDS disagrees with Source::supports_discover",
    );
    Probe::Checked
}

#[tokio::test(flavor = "multi_thread")]
async fn sink_allowlists_match_trait_methods() {
    let mut skipped_unexpected = Vec::new();
    let mut checked = 0usize;
    for kind in registry::sink_kinds() {
        match probe_sink(kind).await {
            Probe::Checked => checked += 1,
            Probe::Skipped(reason) => {
                // Only a connect-required skip is allowed. Any other build
                // failure means a new connector became un-probeable — surface it.
                if !is_connect_required(kind) {
                    skipped_unexpected.push(format!("{kind}: {reason}"));
                }
            }
        }
    }
    assert!(
        skipped_unexpected.is_empty(),
        "these sinks failed to build offline but are not on the CONNECT_REQUIRED \
         skip-list — add them (with a reason) or fix the config synthesizer:\n{}",
        skipped_unexpected.join("\n")
    );
    // The offline set is non-empty (guards against the synthesizer silently
    // skipping everything and the test asserting nothing).
    assert!(checked > 0, "no sinks were actually probed");
}

#[tokio::test(flavor = "multi_thread")]
async fn source_allowlists_match_trait_methods() {
    let mut skipped_unexpected = Vec::new();
    let mut checked = 0usize;
    for kind in registry::source_kinds() {
        match probe_source(kind).await {
            Probe::Checked => checked += 1,
            Probe::Skipped(reason) => {
                if !is_connect_required(kind) {
                    skipped_unexpected.push(format!("{kind}: {reason}"));
                }
            }
        }
    }
    assert!(
        skipped_unexpected.is_empty(),
        "these sources failed to build offline but are not on the CONNECT_REQUIRED \
         skip-list — add them (with a reason) or fix the config synthesizer:\n{}",
        skipped_unexpected.join("\n")
    );
    assert!(checked > 0, "no sources were actually probed");
}

/// The skip-list must not name a connector that isn't compiled in, and every
/// entry must carry a non-empty reason. Keeps the list honest as connectors come
/// and go.
#[test]
fn connect_required_list_is_well_formed() {
    for (kind, reason) in CONNECT_REQUIRED {
        assert!(!reason.trim().is_empty(), "{kind}: skip reason must be non-empty");
    }
}

