        "localhost:9092".into()
    } else if f.contains("url") || f.contains("uri") || f.contains("endpoint") {
        "http://localhost:1/".into()
    } else if f.contains("host") {
        "localhost".into()
    } else if f.contains("path") || f.contains("file") {
        "/tmp/faucet_parity_probe".into()
    } else if f.contains("region") {
        "us-east-1".into()
    } else {
