    let defs = schema
        .get("$defs")
        .or_else(|| schema.get("definitions"))
        .and_then(Value::as_object)
        .unwrap_or(&empty);
    synthesize(schema, defs, "", 0)
}

/// Outcome of trying to probe one connector.
enum Probe {
    Checked,
    Skipped(String),
}

async fn probe_sink(kind: &str) -> Probe {
    if is_connect_required(kind) {
        return Probe::Skipped("connect-required".into());
    }
    let schema = match registry::sink_schema(kind) {
        Ok(s) => s,
        Err(e) => return Probe::Skipped(format!("no schema: {e}")),
    };
    let cfg = minimal_config(&format!("sink:{kind}"), &schema);
    let auth: AuthCatalog = HashMap::new();
    let sink = match registry::build_sink(kind, cfg, &auth).await {
        Ok(s) => s,
        Err(e) => return Probe::Skipped(format!("build failed: {e}")),
    };

