1	//! #465 Part 1 — cross-check the registry capability *allowlists* against the
2	//! trait methods on a real, built connector, so the two can never silently
3	//! drift.
4	//!
5	//! The gates in `expand.rs` / `topology.rs` trust the hand-maintained allowlists
6	//! in `registry.rs` (`IDEMPOTENT_SINK_KINDS`, `UPSERT_SINK_KINDS`,
7	//! `SCHEMA_EVOLUTION_SINK_KINDS`, `EXACTLY_ONCE_SOURCE_KINDS`,
8	//! `DISCOVER_SOURCE_KINDS`). The pipeline and each connector trust the trait
9	//! methods (`Sink::supports_idempotent_writes` / `supported_write_modes` /
10	//! `supports_schema_evolution`; `Source::supports_exactly_once` /
11	//! `supports_discover`). If those two ever disagree the worst case is a run that
12	//! passes the exactly-once gate but silently loses the guarantee — the worst bug
13	//! class in this project. This test builds each connector and asserts
14	//! allowlist == trait on every dimension.
15	//!
16	//! **Coverage model.** A connector whose `new()` opens a live connection eagerly
17	//! (the sqlx `.connect()` sinks, tiberius, Spanner, the Iceberg catalog, the CDC
18	//! sources) cannot be constructed in an offline unit test, so it is *skipped*
19	//! rather than failed. To guarantee the check never silently degrades to probing
20	//! nothing, [`MUST_CHECK_SINKS`] / [`MUST_CHECK_SOURCES`] name connectors known
21	//! to build offline — including the drift-critical capable sinks (sqlite, redis,
22	//! mongodb, elasticsearch) — and the test fails if any of those is *not* probed.
23	//! In CI the whole suite runs under `--all-features`, so every compiled
24	//! connector that can be built offline is exercised.
25	
26	use std::collections::{HashMap, HashSet};
27	
28	use faucet_cli::auth_catalog::AuthCatalog;
29	use faucet_cli::registry;
30	use serde_json::{Map, Value, json};
31	use std::time::Duration;
32	
33	/// A connector whose `new()` tries to reach a live endpoint could block on a
34	/// connection attempt with the synthesized placeholder config. Bound every build
35	/// so such a connector is skipped (treated as un-probeable offline) instead of
36	/// stalling the suite under `--all-features`.
37	const BUILD_TIMEOUT: Duration = Duration::from_secs(4);
38	
39	/// Sinks that MUST be probeable offline. A curated set of connectors that
40	/// construct without a live endpoint, deliberately including capable sinks so
41	/// the tier-1 allowlists (idempotent / upsert / schema-evolution) are actually
42	/// cross-checked, not skipped. The test fails if any is not probed.
43	/// Deliberately TLS-free: each constructs without a network client, so it can't
44	/// hit rustls' multi-provider panic under `--all-features` — keeping the MUST
45	/// guarantee robust across feature sets. sqlite/redis/mongodb still cover the
46	/// tier-1 allowlists (idempotent + upsert + schema-evolution). reqwest-based
47	/// connectors (elasticsearch/http/…) are checked best-effort when they build.
48	const MUST_CHECK_SINKS: &[&str] = &[
49	    "jsonl", "csv", "stdout", "sqlite",  // idempotent + upsert + schema-evolution
50	    "redis",   // idempotent
51	    "mongodb", // idempotent + upsert
52	];
53	
54	/// Sources that MUST be probeable offline (TLS-free — see [`MUST_CHECK_SINKS`]).
55	const MUST_CHECK_SOURCES: &[&str] = &["csv", "sqlite", "redis", "mongodb"];
56	
57	/// Partial config overrides, deep-merged onto the schema-synthesized config
58	/// where the generic placeholder is not accepted by a connector's `new()` (a
59	/// scheme-specific URL, an enum variant the synthesizer can't guess). Keyed by
60	/// `"source:<kind>"` / `"sink:<kind>"`. Only the offending fields need setting.
61	fn config_override(key: &str) -> Option<Value> {
62	    let v = match key {
63	        "sink:sqlite" => json!({ "database_url": "sqlite::memory:" }),
64	        "source:sqlite" => json!({ "database_url": "sqlite::memory:", "query": "SELECT 1" }),
65	        "sink:mongodb" | "source:mongodb" => {
66	            json!({ "connection_uri": "mongodb://localhost:27017" })
67	        }
68	        "sink:redis" | "source:redis" => json!({ "url": "redis://localhost:6379" }),
69	        _ => return None,
70	    };
71	    Some(v)
72	}
73	
74	/// Recursive deep-merge: object values merge key-by-key, everything else in
75	/// `overlay` replaces `base`.
76	fn deep_merge(base: &mut Value, overlay: Value) {
77	    match (base, overlay) {
78	        (Value::Object(b), Value::Object(o)) => {
79	            for (k, v) in o {
80	                deep_merge(b.entry(k).or_insert(Value::Null), v);
81	            }
82	        }
83	        (b, o) => *b = o,
84	    }
85	}
86	
87	/// Synthesize a minimal, type-valid config instance from a connector's JSON
88	/// Schema: resolve `$ref`, take the first `enum`/`oneOf` variant, and fill every
89	/// `required` field with a field-name-aware placeholder. Enough to satisfy
90	/// `serde` + a lazily-constructing `new()`.
91	fn synthesize(schema: &Value, defs: &Map<String, Value>, field: &str, depth: u32) -> Value {
92	    if depth > 12 {
93	        return Value::Null;
94	    }
95	    if let Some(r) = schema.get("$ref").and_then(Value::as_str) {
96	        let name = r.rsplit('/').next().unwrap_or(r);
97	        return match defs.get(name) {
98	            Some(target) => synthesize(target, defs, field, depth + 1),
99	            None => Value::Null,
100	        };
101	    }
102	    if let Some(c) = schema.get("const") {
103	        return c.clone();
104	    }
105	    if let Some(first) = schema
106	        .get("enum")
107	        .and_then(Value::as_array)
108	        .and_then(|a| a.first())
109	    {
110	        return first.clone();
111	    }
112	    for combinator in ["oneOf", "anyOf", "allOf"] {
113	        if let Some(first) = schema
114	            .get(combinator)
115	            .and_then(Value::as_array)
116	            .and_then(|a| a.first())
117	        {
118	            return synthesize(first, defs, field, depth + 1);
119	        }
120	    }
121	
122	    let ty = schema.get("type").and_then(|t| match t {
123	        Value::String(s) => Some(s.clone()),
124	        Value::Array(a) => a
125	            .iter()
126	            .filter_map(Value::as_str)
127	            .find(|s| *s != "null")
128	            .map(String::from),
129	        _ => None,
130	    });
131	
132	    let is_object =
133	        ty.as_deref() == Some("object") || (ty.is_none() && schema.get("properties").is_some());
134	    if is_object {
135	        let props = schema
136	            .get("properties")
137	            .and_then(Value::as_object)
138	            .cloned()
139	            .unwrap_or_default();
140	        let required: Vec<String> = schema
141	            .get("required")
142	            .and_then(Value::as_array)
143	            .map(|a| {
144	                a.iter()
145	                    .filter_map(Value::as_str)
146	                    .map(String::from)
147	                    .collect()
148	            })
149	            .unwrap_or_default();
150	        let mut obj = Map::new();
151	        for name in &required {
152	            if let Some(prop) = props.get(name) {
153	                obj.insert(name.clone(), synthesize(prop, defs, name, depth + 1));
154	            }
155	        }
156	        return Value::Object(obj);
157	    }
158	
159	    match ty.as_deref() {
160	        Some("string") => Value::String(placeholder_string(field)),
161	        Some("integer") | Some("number") => json!(1),
162	        Some("boolean") => json!(false),
163	        Some("array") => json!([]),
164	        _ => Value::Null,
165	    }
166	}
167	
